# -*- coding: utf-8 -*-
"""Emit assets/js/images.js so the page works straight from file:// (no fetch)."""
import io, json, os

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
src = io.open(os.path.join(ROOT, "assets", "js", "images.json"), encoding="utf-8").read()
out = os.path.join(ROOT, "assets", "js", "images.js")

body = json.dumps(json.loads(src), ensure_ascii=False, indent=2)
io.open(out, "w", encoding="utf-8").write(
    "/* Generated by tools/build_images_js.py - do not edit by hand.\n"
    "   Image credits for every Wikimedia Commons picture used in this book. */\n"
    "window.IMAGE_CREDITS = " + body + ";\n")
print("wrote", out, os.path.getsize(out), "bytes")
